Based on the screenshots and your report, the problem is that when you set

```yaml
code-tools:
  source: "https://…"
```

the code-tools post-processor never “keeps” the source because in `resolveKeepSource()` we only look for `source === undefined` or `=== true` – we never treat a _string_ URL as “keep source”.  Consequently `format.render[kKeepSource]` stays false and the menu never appears.

Below is a single *SEARCH/REPLACE* that will treat a string URL as a valid `source` value.  After this change, `source: "https://…"` will correctly enable the code-tools menu and view-source button.

```javascript
### src/command/render/codetools.ts
<<<<<<< SEARCH
export function resolveKeepSource(
  format: Format,
  engine: ExecutionEngine,
  target: ExecutionTarget,
) {
  // keep source if requested (via keep-source or code-tools), we are targeting html,
  // and engine can keep it (e.g. we wouldn't keep an .ipynb file as source)
  const codeTools = format.render?.[kCodeTools];
  if (
    codeTools === true ||
    (typeof (codeTools) === "object" &&
      (codeTools?.source === undefined || codeTools?.source === true))
  ) {
    format.render[kKeepSource] = true;
  }
  format.render[kKeepSource] = format.render[kKeepSource] &&
    isHtmlOutput(format.pandoc, true) &&
    formatHasBootstrap(format) &&
    executionEngineCanKeepSource(engine, target);
}
